if action is None:
    result = {'action': None, 'candidates': [(a.objectName(), a.text()) for a in mw.findChildren(QAction) if 'nnotation' in (a.objectName() or '')]}
else:
    action.trigger()
    tb = mw.findChild(QToolBar, 'mAnnotationsToolBar')
    result = {'action': action.objectName(), 'checked': action.isChecked(), 'toolbar_visible': tb.isVisible() if tb else None}"}
